import { Router } from "express";
import { createAccount, deleteAccount, getAccountById, getAccounts, updateAccount, } from "../controllers/account.controller";
import { requiredAuth } from "../middleware/auth.middleware";
import { requireRole } from "../middleware/role.middleware";
const router = Router();
router.post("/", requiredAuth, requireRole("admin"), createAccount);
router.get("/", requiredAuth, requireRole("admin"), getAccounts);
router.get("/:id", requiredAuth, requireRole("admin"), getAccountById);
router.put("/:id", requiredAuth, requireRole("admin"), updateAccount);
router.delete("/:id", requiredAuth, requireRole("admin"), deleteAccount);
export default router;
